t * An id that is not listed here (a future preset, or one a theme pack adds) keeps its SKINS\n\t\t * order and follows the listed ones, so nothing disappears just because this list lagged.\n\t\t */\n\t\tconst SKIN_CARD_ORDER = [\"mist\", \"ivory\", \"rose\", \"abyss\", \"aurora\", \"nebula\", \"ember\", \"midnight\"];\n\n\t\t/** SKINS in card order: the listed ids first, then anything this build added later. */\n\t\tfunction skinsInCardOrder() {\n\t\t\tconst byId = new Map(SKINS.map((skin) => [skin.id, skin]));\n\t\t\tconst listed = new Set(SKIN_CARD_ORDER);\n\t\t\tconst ordered = SKIN_CARD_ORDER.map((id) => byId.get(id)).filter(Boolean);\n\t\t\treturn ordered.concat(SKINS.filter((skin) => !listed.has(skin.id)));\n\t\t}\n\n\t\t/** Simplified Chinese dictionary (the key-set source of truth). */\n\t\tconst zh = {\n\t\t\t\"zone.theme\": \"主题与配色\",\n\t\t\t\"zone.wallpaper\": \"背景与壁纸\",\n\t\t\t\"zone.packs\": \"导入与导出\",\n\t\t\t\"skin.title\": \"主题皮肤\",\n\t\t\t\"skin.default\": \"默认\",\n\t\t\t\"skin.abyss\": \"沉静蓝\",\n\t\t\t\"skin.aurora\": \"极光青\",\n\t\t\t\"skin.nebula\": \"星云紫\",\n\t\t\t\"skin.ember\": \"余烬橙\",\n\t\t\t\"skin.midnight\": \"子夜黑\",\n\t\t\t\"skin.ivory\": \"iOS 扁平\",\n\t\t\t\"skin.mist\": \"干净明亮\",\n\t\t\t\"skin.rose\": \"Material 粉\",\n\t\t\t\"background.choose\": \"选择图片\",\n\t\t\t\"background.opacity\": \"壁纸能见度\",\n\t\t\t\"background.blur\": \"壁纸模糊度\",\n\t\t\t\"background.sidebarOpacity\": \"侧边栏透明度\",\n\t\t\t\"glass.separateSidebar\": \"单独设置侧边栏透明度\",\n\t\t\t\"glass.separateComposer\": \"单独设置输入框透明度\",\n\t\t\t\"glass.separateModal\": \"单独设置弹窗透明度\",\n\t\t\t\"glass.title\": \"玻璃效果\",\n\t\t\t\"glass.performance\": \"低功耗模式\",\n\t\t\t\"glass.performanceAuto\": \"跟随系统的「减少透明度」设置\",\n\t\t\t\"glass.performanceAutoReset\": \"交还给自动\",\n\t\t\t\"glass.help\": \"越右越透明，越左越实；模糊作用于壁纸与所有玻璃面。\",\n\t\t\t\"material.frosted\": \"毛玻璃\",\n\t\t\t\"material.liquid\": \"液态玻璃\",\n\t\t\t\"material.hint\": \"只换玻璃质感，不动滑杆数值。\",\n\t\t\t\"material.frosted.desc\": \"经典毛玻璃：奶霜质感，文字更清晰\",\n\t\